func (q *Queries) SetServiceResourceVerification(ctx context.Context, arg SetServiceResourceVerificationParams) error {
	_, err := q.db.Exec(ctx, setServiceResourceVerification,
		arg.AssignmentID,
		arg.ResourceID,
		arg.LastVerifiedAt,
		arg.ObservedAt,
		arg.DriftRemediated,
	)
	return err
}

const setServiceResult = `-- name: SetServiceResult :exec
UPDATE resource_actions SET action_revision = $2, attestation_envelope = $3, attestation_certificate = $4, status_document = $5, attested_at = $6, received_at = $7, result_nonce = '', nonce_expires_at = NULL WHERE id = $1
`

type SetServiceResultParams struct {
	ID                     uuid.UUID
	ActionRevision         pgtype.Numeric
	AttestationEnvelope    []byte
	AttestationCertificate []byte
	StatusDocument         []byte
	AttestedAt             pgtype.Timestamptz
	ReceivedAt             pgtype.Timestamptz
}

func (q *Queries) SetServiceResult(ctx context.Context, arg SetServiceResultParams) error {
	_, err := q.db.Exec(ctx, setServiceResult,
		arg.ID,
		arg.ActionRevision,
		arg.AttestationEnvelope,
		arg.AttestationCertificate,
		arg.StatusDocument,
		arg.AttestedAt,
		arg.ReceivedAt,
	)
	return err
}
